syntax:
template <class T>
struct common_type<T> {
    typedef std::decay_t<T> type;  // std::decay_t<T> is a compile-time alias; the compiler resolves this by applying decay transformations to T, such as removing references and cv-qualifiers, before instantiation.
};

code_example:
#include <type_traits>
#include <iostream>
template <class T>
struct common_type {
    typedef std::decay_t<T> type;  // Compile-time type transformation
};
int main() {
    common_type<int&>::type var = 5;  // Instantiates with T = int&, resulting in type = int
    std::cout << var << std::endl;
    return 0;
}
